class Heap {
  constructor(cmp) {
    this.a = []
    this.cmp = cmp
  }
  get size() {
    return this.a.length
  }
  push(x) {
    const a = this.a
    a.push(x)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1
      if (this.cmp(a[i], a[p]) >= 0) break
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
  }
  pop() {
    const a = this.a
    const top = a[0]
    const last = a.pop()
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l
        if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

function earliestArrivals(n, roads, depots) {
  const adj = Array.from({ length: n }, () => [])
  for (const [a, b, minutes] of roads) adj[a].push([b, minutes])
  const best = Array(n).fill(-1)
  const heap = new Heap((x, y) => x[0] - y[0])
  for (const d of depots) heap.push([0, d])
  while (heap.size) {
    const [t, v] = heap.pop()
    if (best[v] !== -1) continue
    best[v] = t
    for (const [u, minutes] of adj[v]) {
      if (best[u] === -1) heap.push([t + minutes, u])
    }
  }
  return best
}

