import heapq

def earliest_arrivals(n, roads, depots):
    adj = [[] for _ in range(n)]
    for a, b, minutes in roads:
        adj[a].append((b, minutes))
    best = [-1] * n
    heap = [(0, d) for d in depots]
    heapq.heapify(heap)
    while heap:
        t, v = heapq.heappop(heap)
        if best[v] != -1:
            continue
        best[v] = t
        for u, minutes in adj[v]:
            if best[u] == -1:
                heapq.heappush(heap, (t + minutes, u))
    return best
